# ============================================================
# 006.0_Optimisation_k_Louvain.R
#
# Objective 1
# Re-optimisation of k for weighted kNN-Louvain clustering in
# the current LAPCOM control population.
#
# This script is exploratory and does NOT impose:
# - a previously selected k (including k = 53 or k = 56);
# - a predefined number of communities;
# - the historical 41/48 partition;
# - a single Louvain seed as evidence of stability.
#
# Analytical principles:
# - robust scores generated by 005_Figure3_PCA.R;
# - normalisation verified separately within each Author;
# - joint analysis of all 89 control fish after normalisation;
# - Euclidean distance in the original four-dimensional robust
#   behavioural space, not in a truncated PCA space;
# - similarity = 1 / (1 + Euclidean distance);
# - weighted, undirected union kNN graph;
# - k scanned from 5 to 80;
# - 100 reproducible Louvain runs for every k;
# - representative partition selected as the ARI medoid across
#   seeds, with modularity and seed used only as tie-breakers;
# - internal indices and stability are reported separately;
# - a three-panel Rajput-S4-style optimisation figure is
#   generated entirely in R;
# - no final k is selected automatically.
# ============================================================

# ------------------------------------------------------------
# 1. Project directory
# ------------------------------------------------------------

base_dir <- normalizePath(
  ".",
  winslash = "/",
  mustWork = TRUE
)

expected_folders <- c(
  "01_Data"
)

missing_folders <- expected_folders[
  !dir.exists(
    file.path(
      base_dir,
      expected_folders
    )
  )
]

if (length(missing_folders) > 0) {
  stop(
    "The script does not appear to be running from the project root.\n",
    "Expected project folder(s) not found:\n",
    paste(
      missing_folders,
      collapse = ", "
    )
  )
}

# ------------------------------------------------------------
# 2. Required packages
# ------------------------------------------------------------

required_packages <- c(
  "dplyr",
  "tibble",
  "ggplot2",
  "igraph"
)

missing_packages <- required_packages[
  !vapply(required_packages, requireNamespace, logical(1), quietly = TRUE)
]

if (length(missing_packages) > 0L) {
  stop(
    "Install the following packages before running the script:\n",
    paste(missing_packages, collapse = ", ")
  )
}

library(dplyr)
library(tibble)
library(ggplot2)
library(igraph)

# ------------------------------------------------------------
# 3. Input and output paths
# ------------------------------------------------------------

objects_dir <- file.path("03_Results", "Objects")
tables_dir <- file.path("03_Results", "Tables")
figures_dir <- file.path("03_Results", "Figures")

for (directory_i in c(objects_dir, tables_dir, figures_dir)) {
  if (!dir.exists(directory_i)) {
    dir.create(directory_i, recursive = TRUE)
  }
}

robust_data_file <- file.path(
  objects_dir,
  "objective1_control_robust_z.rds"
)

if (!file.exists(robust_data_file)) {
  stop(
    "Required robust-control object not found:\n",
    robust_data_file,
    "\n\nRun 005_Figure3_PCA.R before this script."
  )
}

# ------------------------------------------------------------
# 4. Analysis parameters fixed before inspection of results
# ------------------------------------------------------------

robust_variables <- c(
  "distance_rz",
  "crossing_rz",
  "top_entry_rz",
  "top_time_rz"
)

expected_number_of_fish <- 89L
expected_number_of_cohorts <- 4L

k_values <- 5:80

number_of_seed_runs <- 100L
seed_base <- 20260803L
seed_values <- seed_base + seq_len(number_of_seed_runs) - 1L

RNGkind(
  kind = "Mersenne-Twister",
  normal.kind = "Inversion",
  sample.kind = "Rejection"
)

adjacent_ari_threshold <- 0.90
near_optimum_fraction <- 0.05
exact_ari_tolerance <- 1e-12
normalisation_tolerance <- 1e-8

if (
  length(k_values) < 2L ||
  anyDuplicated(k_values) > 0L ||
  any(diff(k_values) != 1L)
) {
  stop("k_values must be a unique, consecutive integer sequence.")
}

if (number_of_seed_runs < 2L) {
  stop("At least two Louvain seed runs are required for stability analysis.")
}

if (anyDuplicated(seed_values) > 0L) {
  stop("The Louvain seed values are not unique.")
}

# ------------------------------------------------------------
# 5. Load and standardise the robust control dataset
# ------------------------------------------------------------

control_robust <- readRDS(robust_data_file)

if (!is.data.frame(control_robust)) {
  stop("objective1_control_robust_z.rds is not a data frame.")
}

required_columns <- c(
  "Author",
  "ID",
  "Treatment",
  robust_variables
)

missing_columns <- setdiff(required_columns, names(control_robust))

if (length(missing_columns) > 0L) {
  stop(
    "The robust control dataset is missing the following columns:\n",
    paste(missing_columns, collapse = ", ")
  )
}

control_robust <- control_robust %>%
  dplyr::mutate(
    Author = as.character(Author),
    ID = as.character(ID),
    Treatment = as.character(Treatment),
    Node_ID = paste(Author, ID, sep = "::")
  )

if (nrow(control_robust) != expected_number_of_fish) {
  stop(
    "Expected ",
    expected_number_of_fish,
    " control fish; found ",
    nrow(control_robust),
    "."
  )
}

if (
  anyNA(control_robust[c("Author", "ID", "Treatment")]) ||
  any(trimws(control_robust$Author) == "") ||
  any(trimws(control_robust$ID) == "") ||
  any(trimws(control_robust$Treatment) == "")
) {
  stop("Missing or empty individual-traceability values were detected.")
}

if (!all(control_robust$Treatment == "Control")) {
  stop("The robust control object contains non-Control observations.")
}

if (
  anyDuplicated(control_robust[c("Author", "ID")]) > 0L ||
  anyDuplicated(control_robust$Node_ID) > 0L
) {
  stop("Duplicated Author + ID keys were detected.")
}

observed_number_of_cohorts <- dplyr::n_distinct(control_robust$Author)

if (observed_number_of_cohorts != expected_number_of_cohorts) {
  stop(
    "Expected ",
    expected_number_of_cohorts,
    " cohorts in Author; found ",
    observed_number_of_cohorts,
    "."
  )
}

non_numeric_variables <- robust_variables[
  !vapply(control_robust[robust_variables], is.numeric, logical(1))
]

if (length(non_numeric_variables) > 0L) {
  stop(
    "The following robust variables are not numeric:\n",
    paste(non_numeric_variables, collapse = ", ")
  )
}

cohort_counts <- control_robust %>%
  dplyr::count(Author, name = "n") %>%
  dplyr::arrange(Author)

# ------------------------------------------------------------
# 6. Verify the 16 cohort-by-variable robust transformations
# ------------------------------------------------------------

cohort_ids <- sort(unique(control_robust$Author))

robust_audit <- dplyr::bind_rows(
  lapply(
    cohort_ids,
    function(cohort_id) {
      cohort_rows <- control_robust$Author == cohort_id

      dplyr::bind_rows(
        lapply(
          robust_variables,
          function(variable_name) {
            values <- control_robust[[variable_name]][cohort_rows]

            tibble::tibble(
              Author = cohort_id,
              Variable = variable_name,
              n = length(values),
              Available_n = sum(is.finite(values)),
              Median_rz = stats::median(values),
              MAD_scaled_rz = stats::mad(
                values,
                center = stats::median(values),
                constant = 1.4826
              ),
              Unique_values = length(unique(values))
            )
          }
        )
      )
    }
  )
)

expected_audit_rows <- expected_number_of_cohorts * length(robust_variables)

if (
  nrow(robust_audit) != expected_audit_rows ||
  any(robust_audit$Available_n != robust_audit$n) ||
  any(!is.finite(robust_audit$Median_rz)) ||
  any(!is.finite(robust_audit$MAD_scaled_rz)) ||
  any(robust_audit$Unique_values < 2L) ||
  any(abs(robust_audit$Median_rz) > normalisation_tolerance) ||
  any(abs(robust_audit$MAD_scaled_rz - 1) > normalisation_tolerance)
) {
  print(as.data.frame(robust_audit), row.names = FALSE)
  stop(
    "The cohort-wise robust-normalisation audit failed. ",
    "Do not optimise k until 005_Figure3_PCA.R has been corrected."
  )
}

# ------------------------------------------------------------
# 7. Construct the joint 89 x 4 behavioural matrix
# ------------------------------------------------------------

X <- control_robust %>%
  dplyr::select(dplyr::all_of(robust_variables)) %>%
  as.matrix()

storage.mode(X) <- "double"
rownames(X) <- control_robust$Node_ID

if (
  nrow(X) != expected_number_of_fish ||
  ncol(X) != length(robust_variables) ||
  any(!is.finite(X)) ||
  any(vapply(as.data.frame(X), function(x) length(unique(x)) < 2L, logical(1)))
) {
  stop("The joint 89 x 4 robust behavioural matrix failed its audit.")
}

if (max(k_values) >= nrow(X)) {
  stop("Every k must be smaller than the number of control fish.")
}

euclidean_distance <- as.matrix(stats::dist(X, method = "euclidean"))

if (
  any(!is.finite(euclidean_distance)) ||
  max(abs(euclidean_distance - t(euclidean_distance))) > 1e-12 ||
  max(abs(diag(euclidean_distance))) > 1e-12
) {
  stop("The Euclidean distance matrix failed its integrity checks.")
}

# ------------------------------------------------------------
# 8. Reusable functions
# ------------------------------------------------------------

combination_2 <- function(x) {
  x * (x - 1) / 2
}

adjusted_rand_index <- function(partition_1, partition_2) {
  if (length(partition_1) != length(partition_2)) {
    stop("ARI partitions have different lengths.")
  }

  contingency_table <- table(partition_1, partition_2)
  sum_cells <- sum(combination_2(contingency_table))
  sum_rows <- sum(combination_2(rowSums(contingency_table)))
  sum_columns <- sum(combination_2(colSums(contingency_table)))
  total_pairs <- combination_2(sum(contingency_table))

  if (total_pairs == 0) {
    return(NA_real_)
  }

  expected_index <- (sum_rows * sum_columns) / total_pairs
  maximum_index <- (sum_rows + sum_columns) / 2
  denominator <- maximum_index - expected_index

  if (abs(denominator) <= sqrt(.Machine$double.eps)) {
    same_relationships <- identical(
      outer(partition_1, partition_1, `==`),
      outer(partition_2, partition_2, `==`)
    )

    return(if (same_relationships) 1 else 0)
  }

  as.numeric((sum_cells - expected_index) / denominator)
}

canonicalise_membership <- function(membership_vector, data_matrix) {
  membership_vector <- as.integer(membership_vector)
  community_labels <- sort(unique(membership_vector))
  individual_composite <- rowMeans(data_matrix)

  community_order <- data.frame(
    Original_cluster = community_labels,
    Composite_centroid = vapply(
      community_labels,
      function(cluster_i) {
        mean(individual_composite[membership_vector == cluster_i])
      },
      numeric(1)
    )
  )

  community_order <- community_order[order(
    -community_order$Composite_centroid,
    community_order$Original_cluster
  ), , drop = FALSE]

  label_map <- stats::setNames(
    seq_len(nrow(community_order)),
    community_order$Original_cluster
  )

  canonical_membership <- unname(
    label_map[as.character(membership_vector)]
  )

  as.integer(canonical_membership)
}

build_union_knn_graph <- function(k_value) {
  number_of_fish <- nrow(X)
  neighbour_index <- matrix(
    NA_integer_,
    nrow = number_of_fish,
    ncol = k_value
  )

  for (fish_i in seq_len(number_of_fish)) {
    ordered_candidates <- order(
      euclidean_distance[fish_i, ],
      seq_len(number_of_fish)
    )

    ordered_candidates <- ordered_candidates[ordered_candidates != fish_i]
    neighbour_index[fish_i, ] <- ordered_candidates[seq_len(k_value)]
  }

  directed_from <- rep(seq_len(number_of_fish), each = k_value)
  directed_to <- as.vector(t(neighbour_index))

  if (
    length(directed_from) != number_of_fish * k_value ||
    any(directed_from == directed_to)
  ) {
    stop("Invalid directed kNN relations at k = ", k_value, ".")
  }

  undirected_from <- pmin(directed_from, directed_to)
  undirected_to <- pmax(directed_from, directed_to)
  undirected_key <- paste(undirected_from, undirected_to, sep = "::")
  keep_edge <- !duplicated(undirected_key)

  undirected_from <- undirected_from[keep_edge]
  undirected_to <- undirected_to[keep_edge]
  edge_distance <- euclidean_distance[
    cbind(undirected_from, undirected_to)
  ]
  edge_similarity <- 1 / (1 + edge_distance)

  edge_table <- data.frame(
    from = control_robust$Node_ID[undirected_from],
    to = control_robust$Node_ID[undirected_to],
    distance = edge_distance,
    weight = edge_similarity,
    stringsAsFactors = FALSE
  )

  vertex_table <- control_robust %>%
    dplyr::transmute(
      name = Node_ID,
      Author,
      ID
    )

  graph_knn <- igraph::graph_from_data_frame(
    d = edge_table,
    directed = FALSE,
    vertices = vertex_table
  )

  if (
    igraph::is_directed(graph_knn) ||
    igraph::vcount(graph_knn) != number_of_fish ||
    igraph::ecount(graph_knn) != nrow(edge_table) ||
    !identical(
      as.character(igraph::V(graph_knn)$name),
      control_robust$Node_ID
    ) ||
    any(igraph::which_loop(graph_knn)) ||
    any(!is.finite(igraph::E(graph_knn)$weight)) ||
    any(igraph::E(graph_knn)$weight <= 0) ||
    any(igraph::E(graph_knn)$weight > 1)
  ) {
    stop("The union kNN graph failed its integrity checks at k = ", k_value, ".")
  }

  list(
    graph = graph_knn,
    neighbour_index = neighbour_index,
    directed_relations = length(directed_from),
    undirected_edges = nrow(edge_table),
    connected_components = igraph::components(graph_knn)$no,
    connected = igraph::is_connected(graph_knn),
    density = igraph::edge_density(graph_knn, loops = FALSE),
    mean_degree = mean(igraph::degree(graph_knn))
  )
}

calinski_harabasz_index <- function(data_matrix, membership_vector) {
  cluster_labels <- sort(unique(membership_vector))
  number_of_clusters <- length(cluster_labels)
  number_of_fish <- nrow(data_matrix)

  if (number_of_clusters < 2L || number_of_clusters >= number_of_fish) {
    return(NA_real_)
  }

  global_centroid <- colMeans(data_matrix)
  between_sum_squares <- 0
  within_sum_squares <- 0

  for (cluster_i in cluster_labels) {
    cluster_data <- data_matrix[membership_vector == cluster_i, , drop = FALSE]
    cluster_centroid <- colMeans(cluster_data)

    between_sum_squares <- between_sum_squares +
      nrow(cluster_data) * sum((cluster_centroid - global_centroid)^2)

    within_sum_squares <- within_sum_squares +
      sum(rowSums((sweep(cluster_data, 2, cluster_centroid))^2))
  }

  if (within_sum_squares <= 0) {
    return(NA_real_)
  }

  as.numeric(
    (between_sum_squares / (number_of_clusters - 1)) /
      (within_sum_squares / (number_of_fish - number_of_clusters))
  )
}

mean_silhouette_index <- function(distance_matrix, membership_vector) {
  cluster_labels <- sort(unique(membership_vector))

  if (length(cluster_labels) < 2L) {
    return(NA_real_)
  }

  silhouette_values <- numeric(length(membership_vector))

  for (fish_i in seq_along(membership_vector)) {
    own_cluster <- membership_vector[fish_i]
    own_members <- which(membership_vector == own_cluster)
    own_members <- own_members[own_members != fish_i]

    if (length(own_members) == 0L) {
      silhouette_values[fish_i] <- 0
      next
    }

    within_distance <- mean(distance_matrix[fish_i, own_members])

    other_cluster_distances <- vapply(
      cluster_labels[cluster_labels != own_cluster],
      function(cluster_i) {
        mean(distance_matrix[fish_i, membership_vector == cluster_i])
      },
      numeric(1)
    )

    nearest_other_distance <- min(other_cluster_distances)
    denominator <- max(within_distance, nearest_other_distance)

    silhouette_values[fish_i] <- if (denominator > 0) {
      (nearest_other_distance - within_distance) / denominator
    } else {
      0
    }
  }

  mean(silhouette_values)
}

davies_bouldin_index <- function(data_matrix, membership_vector) {
  cluster_labels <- sort(unique(membership_vector))
  number_of_clusters <- length(cluster_labels)

  if (number_of_clusters < 2L) {
    return(NA_real_)
  }

  centroids <- t(vapply(
    cluster_labels,
    function(cluster_i) {
      colMeans(data_matrix[membership_vector == cluster_i, , drop = FALSE])
    },
    numeric(ncol(data_matrix))
  ))

  within_scatter <- vapply(
    seq_along(cluster_labels),
    function(cluster_position) {
      cluster_data <- data_matrix[
        membership_vector == cluster_labels[cluster_position],
        ,
        drop = FALSE
      ]

      cluster_centroid <- centroids[cluster_position, ]
      mean(sqrt(rowSums((sweep(cluster_data, 2, cluster_centroid))^2)))
    },
    numeric(1)
  )

  centroid_distances <- as.matrix(stats::dist(centroids, method = "euclidean"))
  comparison_matrix <- matrix(
    NA_real_,
    nrow = number_of_clusters,
    ncol = number_of_clusters
  )

  for (i in seq_len(number_of_clusters)) {
    for (j in seq_len(number_of_clusters)) {
      if (i != j) {
        if (centroid_distances[i, j] <= 0) {
          comparison_matrix[i, j] <- Inf
        } else {
          comparison_matrix[i, j] <-
            (within_scatter[i] + within_scatter[j]) /
            centroid_distances[i, j]
        }
      }
    }
  }

  as.numeric(mean(apply(comparison_matrix, 1, max, na.rm = TRUE)))
}

summarise_ari_values <- function(values) {
  values <- values[is.finite(values)]

  if (length(values) == 0L) {
    return(c(
      Mean = NA_real_,
      Median = NA_real_,
      Minimum = NA_real_,
      Percentile_2_5 = NA_real_,
      Percentile_97_5 = NA_real_
    ))
  }

  c(
    Mean = mean(values),
    Median = stats::median(values),
    Minimum = min(values),
    Percentile_2_5 = unname(stats::quantile(values, 0.025)),
    Percentile_97_5 = unname(stats::quantile(values, 0.975))
  )
}

# ------------------------------------------------------------
# 9. Scan k and assess Louvain stability across seeds
# ------------------------------------------------------------

results_list <- vector("list", length(k_values))
memberships_by_k <- vector("list", length(k_values))
names(memberships_by_k) <- paste0("k_", k_values)

seed_runs_by_k <- vector("list", length(k_values))
names(seed_runs_by_k) <- paste0("k_", k_values)

seed_membership_matrices <- vector("list", length(k_values))
names(seed_membership_matrices) <- paste0("k_", k_values)

for (k_position in seq_along(k_values)) {
  k_value <- k_values[k_position]
  graph_object <- build_union_knn_graph(k_value)
  graph_knn <- graph_object$graph

  seed_memberships <- matrix(
    NA_integer_,
    nrow = nrow(X),
    ncol = number_of_seed_runs,
    dimnames = list(control_robust$Node_ID, as.character(seed_values))
  )

  seed_modularity <- numeric(number_of_seed_runs)
  seed_communities <- integer(number_of_seed_runs)

  for (seed_position in seq_along(seed_values)) {
    seed_value <- seed_values[seed_position]
    set.seed(seed_value)

    louvain_model <- igraph::cluster_louvain(
      graph_knn,
      weights = igraph::E(graph_knn)$weight
    )

    membership_seed <- as.integer(igraph::membership(louvain_model))
    names(membership_seed) <- igraph::V(graph_knn)$name
    membership_seed <- membership_seed[control_robust$Node_ID]

    if (anyNA(membership_seed)) {
      stop(
        "Missing Louvain membership at k = ",
        k_value,
        ", seed = ",
        seed_value,
        "."
      )
    }

    membership_seed <- canonicalise_membership(membership_seed, X)

    seed_memberships[, seed_position] <- membership_seed
    seed_communities[seed_position] <- length(unique(membership_seed))
    seed_modularity[seed_position] <- igraph::modularity(
      graph_knn,
      membership_seed,
      weights = igraph::E(graph_knn)$weight
    )
  }

  seed_pairwise_ari <- matrix(
    1,
    nrow = number_of_seed_runs,
    ncol = number_of_seed_runs,
    dimnames = list(as.character(seed_values), as.character(seed_values))
  )

  for (i in seq_len(number_of_seed_runs - 1L)) {
    for (j in seq.int(i + 1L, number_of_seed_runs)) {
      ari_ij <- adjusted_rand_index(
        seed_memberships[, i],
        seed_memberships[, j]
      )

      seed_pairwise_ari[i, j] <- ari_ij
      seed_pairwise_ari[j, i] <- ari_ij
    }
  }

  mean_ari_to_other_seeds <- vapply(
    seq_len(number_of_seed_runs),
    function(seed_position) {
      mean(seed_pairwise_ari[seed_position, -seed_position])
    },
    numeric(1)
  )

  reference_candidates <- which(
    abs(mean_ari_to_other_seeds - max(mean_ari_to_other_seeds)) <=
      exact_ari_tolerance
  )

  if (length(reference_candidates) > 1L) {
    candidate_modularity <- seed_modularity[reference_candidates]
    reference_candidates <- reference_candidates[
      abs(candidate_modularity - max(candidate_modularity)) <=
        exact_ari_tolerance
    ]
  }

  reference_seed_position <- min(reference_candidates)
  reference_membership <- seed_memberships[, reference_seed_position]
  reference_seed <- seed_values[reference_seed_position]

  ari_to_reference <- vapply(
    seq_len(number_of_seed_runs),
    function(seed_position) {
      adjusted_rand_index(
        seed_memberships[, seed_position],
        reference_membership
      )
    },
    numeric(1)
  )

  pairwise_ari_values <- seed_pairwise_ari[upper.tri(seed_pairwise_ari)]
  ari_reference_summary <- summarise_ari_values(ari_to_reference)
  ari_pairwise_summary <- summarise_ari_values(pairwise_ari_values)

  community_count_table <- sort(
    table(seed_communities),
    decreasing = TRUE
  )
  modal_communities <- as.integer(names(community_count_table)[1])
  modal_community_rate <- as.numeric(community_count_table[1]) /
    number_of_seed_runs

  reference_clusters <- length(unique(reference_membership))
  reference_cluster_sizes <- sort(as.integer(table(reference_membership)))

  calinski_harabasz <- calinski_harabasz_index(X, reference_membership)
  silhouette <- mean_silhouette_index(
    euclidean_distance,
    reference_membership
  )
  davies_bouldin <- davies_bouldin_index(X, reference_membership)

  if (
    any(!is.finite(c(
      seed_modularity,
      ari_to_reference,
      pairwise_ari_values,
      calinski_harabasz,
      silhouette,
      davies_bouldin
    )))
  ) {
    stop("A non-finite optimisation metric was produced at k = ", k_value, ".")
  }

  memberships_by_k[[k_position]] <- tibble::tibble(
    k = k_value,
    Author = control_robust$Author,
    ID = control_robust$ID,
    Node_ID = control_robust$Node_ID,
    Cluster = reference_membership,
    Reference_seed = reference_seed
  )

  seed_runs_by_k[[k_position]] <- tibble::tibble(
    k = k_value,
    Seed = seed_values,
    Communities = seed_communities,
    Weighted_modularity = seed_modularity,
    Mean_ARI_to_other_seeds = mean_ari_to_other_seeds,
    ARI_to_reference = ari_to_reference,
    Reference_run = seq_along(seed_values) == reference_seed_position
  )

  seed_membership_matrices[[k_position]] <- seed_memberships

  results_list[[k_position]] <- tibble::tibble(
    k = k_value,
    Clusters = reference_clusters,
    Cluster_sizes = paste(reference_cluster_sizes, collapse = "; "),
    Minimum_cluster_size = min(reference_cluster_sizes),
    Maximum_cluster_size = max(reference_cluster_sizes),
    Minimum_cluster_proportion = min(reference_cluster_sizes) / nrow(X),
    Maximum_cluster_proportion = max(reference_cluster_sizes) / nrow(X),
    Calinski_Harabasz = calinski_harabasz,
    Silhouette = silhouette,
    Davies_Bouldin = davies_bouldin,
    Weighted_modularity = seed_modularity[reference_seed_position],
    Maximum_seed_modularity = max(seed_modularity),
    Mean_seed_modularity = mean(seed_modularity),
    SD_seed_modularity = stats::sd(seed_modularity),
    Reference_seed = reference_seed,
    Reference_mean_ARI_to_other_seeds =
      mean_ari_to_other_seeds[reference_seed_position],
    Mean_ARI_to_reference = unname(ari_reference_summary["Mean"]),
    Median_ARI_to_reference = unname(ari_reference_summary["Median"]),
    Minimum_ARI_to_reference = unname(ari_reference_summary["Minimum"]),
    ARI_to_reference_percentile_2_5 =
      unname(ari_reference_summary["Percentile_2_5"]),
    ARI_to_reference_percentile_97_5 =
      unname(ari_reference_summary["Percentile_97_5"]),
    Exact_reference_recovery_rate = mean(
      ari_to_reference >= 1 - exact_ari_tolerance
    ),
    Mean_pairwise_seed_ARI = unname(ari_pairwise_summary["Mean"]),
    Median_pairwise_seed_ARI = unname(ari_pairwise_summary["Median"]),
    Minimum_pairwise_seed_ARI = unname(ari_pairwise_summary["Minimum"]),
    Pairwise_seed_ARI_percentile_2_5 =
      unname(ari_pairwise_summary["Percentile_2_5"]),
    Pairwise_seed_ARI_percentile_97_5 =
      unname(ari_pairwise_summary["Percentile_97_5"]),
    Modal_seed_communities = modal_communities,
    Modal_seed_community_rate = modal_community_rate,
    Minimum_seed_communities = min(seed_communities),
    Maximum_seed_communities = max(seed_communities),
    Reference_matches_modal_community_count =
      reference_clusters == modal_communities,
    Directed_kNN_relations = graph_object$directed_relations,
    Undirected_edges = graph_object$undirected_edges,
    Graph_density = graph_object$density,
    Mean_degree = graph_object$mean_degree,
    Connected_components = graph_object$connected_components,
    Connected = graph_object$connected
  )

  cat(
    "Completed k = ",
    k_value,
    ": ",
    reference_clusters,
    " reference communities; median seed ARI = ",
    sprintf("%.3f", unname(ari_reference_summary["Median"])),
    ".\n",
    sep = ""
  )
}

results_by_k <- dplyr::bind_rows(results_list) %>%
